import 'package:flutter/material.dart';class ReplyQuoteCard extends StatelessWidget {  final String senderName;  final String quotedText;  final VoidCallback onCancel;  const ReplyQuoteCard({    super.key,    required this.senderName,    required this.quotedText,    required this.onCancel,  });  @override  Widget build(BuildContext context) {    return Container(      margin: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),      padding: const EdgeInsets.all(8),      decoration: BoxDecoration(        color: Colors.grey.withOpacity(0.2),        borderRadius: BorderRadius.circular(8),        border: const Border(          left: BorderSide(color: Colors.blue, width: 3),        ),      ),      child: Row(        children: [          Expanded(            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Text(                  senderName,                  style: const TextStyle(                    color: Colors.blue,                    fontWeight: FontWeight.bold,                    fontSize: 12,                  ),                ),                Text(                  quotedText,                  style: const TextStyle(color: Colors.white70, fontSize: 14),                  maxLines: 2,                  overflow: TextOverflow.ellipsis,                ),              ],            ),          ),          IconButton(            icon: const Icon(Icons.close, size: 18),            onPressed: onCancel,            padding: EdgeInsets.zero,            constraints: const BoxConstraints(),          ),        ],      ),    );  }}